import {writeFileSync} from 'node:fs';
import {SqliteAgentTriggers,SqliteAgentDefinitions,createAgentEventIngress,createPaddleWebhookAdapter,createTelegramWebhookAdapter,createLinearWebhookAdapter} from '../../dist/index.js';
const [path,definitionPath,barrier,phase,mode]=process.argv.slice(2),hold=()=>{writeFileSync(barrier,phase);Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0);};
try{const triggers=new SqliteAgentTriggers(path),definitions=new SqliteAgentDefinitions(definitionPath);if(phase==='receipt'){triggers.db.function('test_ingress_barrier',()=>{hold();return 0;});triggers.db.exec('CREATE TRIGGER test_ingress_crash BEFORE INSERT ON agent_trigger_receipts BEGIN SELECT test_ingress_barrier(); END');}else{const enqueue=triggers.enqueue.bind(triggers);triggers.enqueue=(...args)=>{const result=enqueue(...args);hold();return result;};}const authentication=mode==='paddle'?createPaddleWebhookAdapter({identity:{tenantId:'tenant',principalId:'sender',sourceId:'source'},agentId:'agent',secret:'paddle-secret-abcdefghijklmnop'}):mode==='linear'?createLinearWebhookAdapter({identity:{tenantId:'tenant',principalId:'sender',sourceId:'source'},agentId:'agent',organizationId:'org-1',webhookId:'hook-1',eventType:'Issue',secret:'L'.repeat(32)}):mode==='telegram'?createTelegramWebhookAdapter({identity:{tenantId:'tenant',principalId:'sender',sourceId:'source'},agentId:'agent',updateTypes:['message','edited_message'],secret:'A'.repeat(32)}):{authenticate:req=>req.headers.authorization==='Bearer trusted'?{tenantId:'tenant',principalId:'sender',sourceId:'source'}:undefined};const ingress=createAgentEventIngress({triggers,definitions,maxPending:10,...authentication,authorize:()=>true,traceParent:()=> '00-0123456789abcdef0123456789abcdef-0123456789abcdef-01'});ingress.listen(0,'127.0.0.1',()=>process.send?.({port:ingress.address().port}));}catch(error){process.send?.({error:String(error)});process.exitCode=1;}
